import json, re, random, chess, sys
rules = json.load(open('/tmp/obench-cell-8n04nns7/bench_opencode_regex-chess_0r9bzwvh/re.json'))
def run(fen):
    for p, r in rules: fen = re.sub(p, r, fen)
    return fen.split("\n")
def expected(fen):
    b = chess.Board(fen); s = set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN: continue
        c = b.copy(); c.push(m); s.add(" ".join(c.fen().split()[:-2]))
    return s
def check(fen):
    ours = [" ".join(x.split(" ")[:-2]) for x in run(fen)]
    exp = expected(fen)
    ok = len(ours) == len(exp) and all(x in exp or x.rpartition(" ")[0]+" -" in exp for x in ours)
    if not ok:
        print("FAIL", fen); print(sorted(ours)); print(sorted(exp)); sys.exit(1)
f = "<REDACTED_B64> w kq - 0 1"
print(run(f))
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
n = 0
for g in range(300):
    b = chess.Board()
    while not b.is_game_over() and b.ply() < 300:
        if b.turn == chess.WHITE:
            check(b.fen()); n += 1
        ms = list(b.legal_moves)
        # bias toward captures/pawn moves for variety
        b.push(random.choice(ms))
print("ok", n)
EOF
